window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-09-01","title":"Portfolio Risk and Return: Part I","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[13,70],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[66,83],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[4,48],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-01-LOS01","learning_goal_vi":"Mô tả đặc điểm các nhóm tài sản chủ yếu khi xây dựng danh mục.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":16},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":67},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":5}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS02","learning_goal_vi":"Giải thích tâm lý ngại rủi ro và ý nghĩa trong lựa chọn danh mục.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":22},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":68},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":8}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS03","learning_goal_vi":"Giải thích lựa chọn danh mục tối ưu theo hữu dụng và capital allocation line.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05"],"formula_ids":["F03-01","F03-02","F03-03"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":53},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":69},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":31}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS04","learning_goal_vi":"Tính và diễn giải mean, variance, covariance hoặc correlation dựa trên dữ liệu lịch sử.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05"],"formula_ids":["F04-01","F04-02","F04-03","F04-04"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":32},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":72},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":16}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS05","learning_goal_vi":"Tính và diễn giải portfolio standard deviation.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S05-01","S05-02","S05-03","S05-04","S05-05"],"formula_ids":["F05-01","F05-02"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":35},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":75},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":21}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS06","learning_goal_vi":"Mô tả tác động đa dạng hóa từ tài sản không tương quan hoàn hảo.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S06-01","S06-02","S06-03","S06-04","S06-05"],"formula_ids":["F06-01"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":43},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":76},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":24}},"missing_items":[]},{"los_id":"CFA26-09-01-LOS07","learning_goal_vi":"Mô tả và diễn giải minimum-variance frontier, efficient frontier và global minimum-variance portfolio.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S07-01","S07-02","S07-03","S07-04","S07-05"],"formula_ids":["F07-01","F07-02"],"example_ids":["E07-01","E07-02"],"question_ids":["Q07-01","Q07-02","Q07-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":49},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":79},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":28}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-01-LOS01"],"heading_vi":"Lợi suất, rủi ro và thanh khoản là ba tiêu chí","body_vi":"Trong xây dựng danh mục phải xét đồng thời lợi suất kỳ vọng, độ phân tán lợi suất, khả năng bán tài sản mà không làm giảm giá mạnh, lạm phát và kỳ hạn đầu tư. Lợi suất lịch sử cao không bảo đảm lợi suất kỳ vọng cao ở kỳ tới; so sánh cần nhất quán về loại tiền, kỳ và điều chỉnh lạm phát."},{"id":"S01-02","los_ids":["CFA26-09-01-LOS01"],"heading_vi":"Tiền mặt và công cụ ngắn hạn","body_vi":"Cash equivalents và tín phiếu ngắn hạn thường có biến động giá thấp, khả năng thanh khoản cao; rủi ro tái đầu tư và rủi ro sức mua vẫn tồn tại. Nhà đầu tư có nghĩa vụ chi trả ngắn hạn không nên chỉ nhìn lợi suất cao của cổ phiếu."},{"id":"S01-03","los_ids":["CFA26-09-01-LOS01"],"heading_vi":"Trái phiếu và cổ phiếu","body_vi":"Trái phiếu tạo dòng tiền hợp đồng, chịu duration, credit spread và default risk; cổ phiếu là quyền hưởng phần còn lại, lợi suất dài hạn biến động lớn, phụ thuộc lợi nhuận, định giá và tăng trưởng. Cổ phiếu có thể tạo lợi suất cao trong dài hạn nhưng tổn thất một năm có thể rất lớn."},{"id":"S01-04","los_ids":["CFA26-09-01-LOS01"],"heading_vi":"Bất động sản và tài sản thay thế","body_vi":"Real estate, private capital, commodities có thanh khoản, cách định giá, đòn bẩy, phí và mức công khai thông tin khác chứng khoán niêm yết. Correlation lịch sử thấp của tài sản định giá không thường xuyên có thể bị làm mượt giá chứ không chứng minh phân tán rủi ro thực."},{"id":"S01-05","los_ids":["CFA26-09-01-LOS01"],"heading_vi":"Cân nhắc đồng tiền và thuế","body_vi":"Đầu tư tài sản nước ngoài có thêm foreign-exchange risk; lợi suất trước thuế không bằng lợi suất sau thuế. So sánh nhóm tài sản phải xét chu kỳ kinh tế, thời gian đầu tư và khả năng chịu lỗ."},{"id":"S02-01","los_ids":["CFA26-09-01-LOS02"],"heading_vi":"Risk aversion và mức đền bù rủi ro","body_vi":"Risk-averse investor yêu cầu lợi suất kỳ vọng tăng khi chấp nhận biến động cao hơn. Risk-neutral chỉ quan tâm lợi suất kỳ vọng, còn risk-seeking có thể thích phân phối rủi ro hơn ở cùng kỳ vọng. Không nên đánh đồng risk tolerance với việc thích sản phẩm có coupon cao."},{"id":"S02-02","los_ids":["CFA26-09-01-LOS02"],"heading_vi":"Hàm hữu dụng mean-variance","body_vi":"Một biểu diễn phổ biến là U=E(R)−0,5Aσ², trong đó A>0 biểu thị mức độ ghét rủi ro. Hai danh mục lợi suất kỳ vọng bằng nhau thì danh mục có σ nhỏ hơn cho U cao hơn; với cùng σ, danh mục E(R) lớn hơn cho U cao hơn."},{"id":"S02-03","los_ids":["CFA26-09-01-LOS02"],"heading_vi":"Đường bàng quan","body_vi":"Indifference curve nối các tổ hợp E(R), σ có cùng U; đường dốc lên với người ghét rủi ro. A lớn đòi hỏi lợi suất bù đắp tăng nhanh hơn khi σ tăng; trên đồ thị E(R)−σ, investor rất ngại rủi ro có đường bàng quan dốc hơn."},{"id":"S02-04","los_ids":["CFA26-09-01-LOS02"],"heading_vi":"Risk capacity khác risk attitude","body_vi":"Khả năng chịu rủi ro phụ thuộc tài sản, nghĩa vụ, nguồn thu và kỳ hạn; mức sẵn lòng chấp nhận rủi ro là tâm lý. Phân bổ thực tế phải tôn trọng yếu tố hạn chế hơn, ngay cả khi nhà đầu tư tin rằng mình có thể chấp nhận lỗ."},{"id":"S02-05","los_ids":["CFA26-09-01-LOS02"],"heading_vi":"Cảnh báo đơn vị tính","body_vi":"Công thức U=E(R)−0,5Aσ² thường giả định lợi suất ở dạng số thập phân; nhập E(R)=10 và σ=20 thay vì 0,10 và 0,20 sẽ làm kết quả sai nghiêm trọng. Sai đơn vị dẫn đến so sánh utility không có ý nghĩa; cần đổi mọi return và volatility sang cùng đơn vị trước khi bình phương độ lệch chuẩn."},{"id":"S03-01","los_ids":["CFA26-09-01-LOS03"],"heading_vi":"Capital allocation line","body_vi":"CAL gồm các tổ hợp phân bổ giữa risk-free asset và một risky portfolio P: điểm y=0 chỉ giữ tài sản phi rủi ro, y=1 giữ 100% P, y>1 vay theo lãi suất giả định để mua thêm P, y<0 thể hiện short risky portfolio. Đường CAL thẳng nếu r_f, E(Rp) và σp không đổi."},{"id":"S03-02","los_ids":["CFA26-09-01-LOS03"],"heading_vi":"Hệ số Sharpe và độ dốc CAL","body_vi":"Slope của CAL là (E(Rp)−r_f)/σp. Trong tập danh mục rủi ro khả thi, CAL cao nhất tiếp xúc efficient frontier tại tangency portfolio (nếu giả định vay/cho vay risk-free cùng lãi suất). Nhà đầu tư với A khác nhau chọn y khác nhau trên cùng CAL tốt nhất."},{"id":"S03-03","los_ids":["CFA26-09-01-LOS03"],"heading_vi":"Điểm tiếp xúc và đường bàng quan","body_vi":"Danh mục tối ưu của nhà đầu tư là điểm tiếp xúc giữa CAL hiệu quả và đường bàng quan cao nhất có thể đạt. Risk aversion càng lớn thì tỷ trọng vốn trong danh mục rủi ro càng nhỏ, các yếu tố còn lại giữ nguyên."},{"id":"S03-04","los_ids":["CFA26-09-01-LOS03"],"heading_vi":"Tỷ trọng tối ưu theo mean-variance utility","body_vi":"Nếu phân bổ y vào P và (1−y) vào tài sản phi rủi ro, tối đa hóa U = r_f + y(E(Rp)−r_f) −0,5A y²σp²; điều kiện đạo hàm bằng 0 cho y*= (E(Rp)−r_f)/(Aσp²). Không áp dụng y* máy móc khi có ràng buộc short/borrowing hoặc lãi vay khác lãi cho vay."},{"id":"S03-05","los_ids":["CFA26-09-01-LOS03"],"heading_vi":"Hai-fund separation và giả định","body_vi":"Khi cùng có thể nắm tangency risky fund và risk-free fund, các nhà đầu tư khác mức ngại rủi ro có thể điều chỉnh y mà không cần thay thành phần danh mục rủi ro. Giao dịch thực tế có taxes, short-sale limits, spread và funding costs làm CAL có thể không còn thẳng duy nhất."},{"id":"S04-01","los_ids":["CFA26-09-01-LOS04"],"heading_vi":"Arithmetic mean và weighted mean","body_vi":"Lợi suất trung bình lịch sử theo mẫu là tổng lợi suất chia số quan sát, dùng cho ước tính kỳ vọng một kỳ nếu các kỳ tương đồng. Mean có trọng số theo xác suất là Σp_iR_i, không dùng tỷ trọng tài sản w khi mục tiêu là mean của cùng một tài sản theo thời gian."},{"id":"S04-02","los_ids":["CFA26-09-01-LOS04"],"heading_vi":"Sample variance và sample standard deviation","body_vi":"Khi dữ liệu là mẫu gồm n lợi suất lịch sử, phương sai mẫu s²=Σ(R_i−Rbar)²/(n−1), standard deviation s=√s². Phương sai tổng thể có mẫu số N; không trộn hai quy ước trong cùng bài."},{"id":"S04-03","los_ids":["CFA26-09-01-LOS04"],"heading_vi":"Covariance và correlation","body_vi":"Sample covariance s_xy=Σ[(x_i−xbar)(y_i−ybar)]/(n−1); sample correlation ρ_xy=s_xy/(s_xs_y). ρ nằm trong [−1,1]; covariance phụ thuộc đơn vị và quy mô volatility, correlation không có đơn vị."},{"id":"S04-04","los_ids":["CFA26-09-01-LOS04"],"heading_vi":"Diễn giải dấu và độ lớn","body_vi":"Covariance/correlation dương là đồng biến về mặt thống kê, âm là nghịch biến; không hàm ý quan hệ nhân quả hay ổn định trong khủng hoảng. Correlation mạnh không bảo đảm giá hai tài sản biến động giống nhau ở mọi kỳ."},{"id":"S04-05","los_ids":["CFA26-09-01-LOS04"],"heading_vi":"Giả định và bẫy","body_vi":"Kiểm tra tất cả lợi suất dùng kỳ giống nhau, dùng số thập phân cho phép tính, xử lý đúng missing data và sample-size. Correlation không xác định nếu σ của một chuỗi bằng 0."},{"id":"S05-01","los_ids":["CFA26-09-01-LOS05"],"heading_vi":"Return và variance danh mục hai tài sản","body_vi":"E(Rp)=wA E(RA)+wB E(RB). Variance phụ thuộc cả volatility riêng và covariance: σp²=wA²σA²+wB²σB²+2wAwBσAσBρAB. Không được lấy weighted average σ trừ trường hợp tương quan đặc biệt."},{"id":"S05-02","los_ids":["CFA26-09-01-LOS05"],"heading_vi":"Đa tài sản và ma trận covariance","body_vi":"Với n tài sản, σp²=Σ_i Σ_j w_iw_jCov(Ri,Rj)=wᵀΣw. Ma trận covariance phải đối xứng, phương sai trên đường chéo và nonnegative semidefinite; lỗi covariance không nhất quán có thể cho variance âm phi lý."},{"id":"S05-03","los_ids":["CFA26-09-01-LOS05"],"heading_vi":"Correlation làm thay đổi σp","body_vi":"Giữ σA,σB và weights cố định, ρ giảm làm portfolio variance giảm khi weights cùng dấu. Ở short position (trọng số âm), quan hệ với ρ cần xem dấu của wAwB. Điều này giải thích vì sao kết luận “tương quan càng thấp càng tốt” cần được xem xét kỹ khi danh mục chứa vị thế bán khống và hedge ratio."},{"id":"S05-04","los_ids":["CFA26-09-01-LOS05"],"heading_vi":"Cách tính kiểm tra ngược","body_vi":"Sau khi tính variance, lấy căn bậc hai để ra σ; kiểm tra đơn vị: nếu σ nhập 20%=0,20 thì σp trả về thập phân. Nếu tất cả tài sản hoàn toàn tương quan dương và trọng số không âm, σp=Σw_iσ_i."},{"id":"S05-05","los_ids":["CFA26-09-01-LOS05"],"heading_vi":"Các giới hạn thực tế","body_vi":"Tương quan lịch sử ước tính sai và thường tăng trong stress. Portfolio sd không nắm bắt downside skew/tail risk, leverage và liquidity risk. Vì thế, kết hợp stress testing, drawdown và liquidity analysis với standard deviation thay vì coi σ là rủi ro duy nhất."},{"id":"S06-01","los_ids":["CFA26-09-01-LOS06"],"heading_vi":"Lợi ích từ correlation dưới +1","body_vi":"Khi nhiều tài sản không hoàn toàn đồng biến, gains và losses có thể bù nhau một phần; σp thấp hơn bình quân có trọng số σ khi weights không âm. Correlation 0 không đồng nghĩa không rủi ro, và hoàn toàn âm −1 có thể loại bỏ rủi ro với tỷ trọng thích hợp."},{"id":"S06-02","los_ids":["CFA26-09-01-LOS06"],"heading_vi":"Rủi ro hệ thống và riêng lẻ","body_vi":"Khi tăng số tài sản, rủi ro idiosyncratic giảm nhưng macro/systematic risk không biến mất. Không thể loại bỏ risk premium từ những cú sốc thị trường chung chỉ bằng cách thêm cổ phiếu cùng beta."},{"id":"S06-03","los_ids":["CFA26-09-01-LOS06"],"heading_vi":"Diminishing marginal benefit","body_vi":"Khi từ 1 lên 5 tài sản thường giảm mạnh rủi ro riêng lẻ hơn từ 100 lên 104 tài sản, nếu các khoản đầu tư đa dạng tương đối và không tập trung vào cùng nhân tố. Kết quả là phải xem marginal contribution to risk của từng tài sản, không đếm số mã đầu tư như thước đo duy nhất."},{"id":"S06-04","los_ids":["CFA26-09-01-LOS06"],"heading_vi":"Vấn đề correlation regime","body_vi":"Tương quan và volatility thay đổi qua thời gian; trong khủng hoảng, nhiều tài sản có thể đồng giảm, làm đa dạng hóa kém hiệu quả. Phải xét concentration theo ngành/quốc gia/rủi ro tín dụng bên cạnh số mã."},{"id":"S06-05","los_ids":["CFA26-09-01-LOS06"],"heading_vi":"Các điều kiện để lợi ích hữu ích","body_vi":"Các tài sản cần có nguồn rủi ro khác biệt, tương quan không quá cao, khả năng tái cân bằng và chi phí giao dịch chấp nhận được. Số tài sản nhiều không tự động tạo efficient portfolio."},{"id":"S07-01","los_ids":["CFA26-09-01-LOS07"],"heading_vi":"Tập hợp danh mục khả thi","body_vi":"Feasible set gồm mọi phối hợp tài sản với các mức E(R), σ; tập hợp hình dạng khác nhau tùy short selling, constraints và ma trận covariance. Minimum-variance frontier là biên bên trái: phương sai thấp nhất ở mỗi mức lợi suất kỳ vọng."},{"id":"S07-02","los_ids":["CFA26-09-01-LOS07"],"heading_vi":"Global minimum-variance portfolio","body_vi":"GMVP là điểm trên minimum-variance frontier có σ nhỏ nhất trên toàn bộ danh mục khả thi. Không nhất thiết là danh mục lợi suất cao nhất; vị trí GMVP phân chia nhánh hữu hiệu và không hữu hiệu."},{"id":"S07-03","los_ids":["CFA26-09-01-LOS07"],"heading_vi":"Efficient frontier của risky assets","body_vi":"Nhánh phía trên GMVP là mean-variance efficient frontier: không có danh mục khác cùng σ nhưng E(R) cao hơn, hoặc cùng E(R) mà σ thấp hơn. Nhánh dưới GMVP bị dominated."},{"id":"S07-04","los_ids":["CFA26-09-01-LOS07"],"heading_vi":"Tangency portfolio và risk-free asset","body_vi":"Thêm risk-free asset với điều kiện vay/cho vay chung tạo CAL; CAL có slope cao nhất tiếp xúc risky efficient frontier tại tangency portfolio. Tangency khác GMVP trừ những trường hợp đặc biệt."},{"id":"S07-05","los_ids":["CFA26-09-01-LOS07"],"heading_vi":"Đọc đồ thị chuẩn","body_vi":"Trên đồ thị trục ngang là σ, trục dọc là E(R): GMVP là cực trái; efficient frontier đi lên từ điểm đó. Không tự kết luận tất cả danh mục nằm trên một đường cong đều hiệu quả."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-01-LOS01"],"expression":"Real return ≈ Nominal return − Inflation","variables":["Quan hệ xấp xỉ với tỷ lệ nhỏ; chính xác (1+r_nominal)/(1+inflation)−1."],"assumptions":["Phải dùng cùng kỳ và cùng đồng tiền."]},{"id":"F02-01","los_ids":["CFA26-09-01-LOS02"],"expression":"U = E(R) − 0.5 A σ²","variables":["A là hệ số risk aversion; σ là standard deviation dạng số thập phân."],"assumptions":["Theo mô hình mean-variance và cùng kỳ lợi suất."]},{"id":"F03-01","los_ids":["CFA26-09-01-LOS03"],"expression":"E(Rc)=rf+y[E(Rp)−rf]","variables":["y là tỷ trọng risky portfolio; y>1 là đầu tư có vay theo giả định."],"assumptions":["Không có giao dịch phí và lãi vay bằng lãi cho vay khi vẽ CAL đơn giản."]},{"id":"F03-02","los_ids":["CFA26-09-01-LOS03"],"expression":"σc = |y| σp","variables":["Tài sản phi rủi ro có variance và covariance bằng 0 trong mô hình."],"assumptions":["Một kỳ, không tính currency mismatch."]},{"id":"F03-03","los_ids":["CFA26-09-01-LOS03"],"expression":"y* = [E(Rp)−rf] / [A σp²]","variables":["A>0; y* tối ưu của utility mean-variance."],"assumptions":["Nếu có hạn mức margin/short cần cắt y* theo ràng buộc."]},{"id":"F04-01","los_ids":["CFA26-09-01-LOS04"],"expression":"R̄ = (Σ R_t)/n","variables":["n số kỳ quan sát."],"assumptions":["Arithmetic mean, không phải geometric compounded return."]},{"id":"F04-02","los_ids":["CFA26-09-01-LOS04"],"expression":"s² = Σ(R_t−R̄)²/(n−1)","variables":["n>1; mean của cùng bộ mẫu."],"assumptions":["Sample variance."]},{"id":"F04-03","los_ids":["CFA26-09-01-LOS04"],"expression":"Cov(Rx,Ry)=Σ[(Rx−R̄x)(Ry−R̄y)]/(n−1)","variables":["Các cặp quan sát đồng thời."],"assumptions":["Sample covariance."]},{"id":"F04-04","los_ids":["CFA26-09-01-LOS04"],"expression":"ρxy = Cov(Rx,Ry)/(sx sy)","variables":["sx,sy>0."],"assumptions":["Correlation trong [−1;1]."]},{"id":"F05-01","los_ids":["CFA26-09-01-LOS05"],"expression":"σp²=wA²σA²+wB²σB²+2wAwBσAσBρ","variables":["wA+wB=1 nếu không có tài sản khác."],"assumptions":["Two-asset variance, same return period."]},{"id":"F05-02","los_ids":["CFA26-09-01-LOS05"],"expression":"σp=√(wᵀΣw)","variables":["Σ covariance matrix."],"assumptions":["Variance không âm; sample estimates must be coherent."]},{"id":"F06-01","los_ids":["CFA26-09-01-LOS06"],"expression":"σp²=wA²σA²+wB²σB²+2wAwBσAσBρ","variables":["Với wA,wB≥0; ρ<1 tạo diversification benefit so với correlation +1."],"assumptions":["Giữ trọng số, standard deviations không đổi khi so sánh."]},{"id":"F07-01","los_ids":["CFA26-09-01-LOS07"],"expression":"GMVP = argmin_w wᵀΣw, subject to 1ᵀw=1","variables":["Các constraints bổ sung như no short sales có thể áp dụng."],"assumptions":["Đòi hỏi ma trận covariance và feasible weights."]},{"id":"F07-02","los_ids":["CFA26-09-01-LOS07"],"expression":"Efficient: minimize σp² given target E(Rp)","variables":["Tập hợp danh mục có cùng expected return."],"assumptions":["Danh mục bị dominated không nằm trên upper frontier."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-01-LOS01"],"problem":"Tiền gửi 4%, lạm phát 3%; tính lợi suất thực.","solution_steps":["Lợi suất thực chính xác = 1,04/1,03−1 = 0,9709%.","Cách tính xấp xỉ 4%−3%=1%, chênh lệch do mẫu số điều chỉnh sức mua."],"answer":"Lợi suất thực khoảng 0,97%, không phải 4%."},{"id":"E01-02","los_ids":["CFA26-09-01-LOS01"],"problem":"Nhà đầu tư cần chi 200 triệu sau 3 tháng, đang cân nhắc cổ phiếu kỳ vọng 12%/năm.","solution_steps":["Nghĩa vụ bằng tiền trong 3 tháng làm giới hạn thanh khoản quan trọng hơn lợi suất kỳ vọng dài hạn.","Phần tiền phải thanh toán nên được phân bổ vào công cụ rất ngắn hạn, chất lượng tín dụng cao và phù hợp đồng tiền chi trả."],"answer":"Không dùng lợi suất cổ phiếu kỳ vọng 12% để đánh đổi tính chắc chắn của khoản chi gần."},{"id":"E02-01","los_ids":["CFA26-09-01-LOS02"],"problem":"Danh mục kỳ vọng 10%, σ=20%, A=3. Tính U.","solution_steps":["Đổi về thập phân: E(R)=0,10; σ²=0,04.","U=0,10−0,5×3×0,04=0,04, tương đương 4% theo biểu diễn hữu dụng."],"answer":"U=4,0% theo đơn vị lợi suất thập phân."},{"id":"E02-02","los_ids":["CFA26-09-01-LOS02"],"problem":"Hai danh mục đều E(R)=9%; A=4; σ_A=10%, σ_B=15%. Chọn.","solution_steps":["U_A=0,09−0,5×4×0,10²=0,07.","U_B=0,09−0,5×4×0,15²=0,045.","A ít biến động hơn cho hữu dụng cao hơn 2,5 điểm phần trăm."],"answer":"Chọn A với U=7% so với B 4,5%."},{"id":"E03-01","los_ids":["CFA26-09-01-LOS03"],"problem":"rf=3%, E(Rp)=11%, σp=20%, A=4. Tỷ trọng y*?","solution_steps":["Excess return=0,11−0,03=0,08; σ²=0,04.","y*=0,08/(4×0,04)=0,50.","Danh mục kỳ vọng 3%+0,5×8%=7%, σ=0,5×20%=10%."],"answer":"Đầu tư 50% vào P và 50% vào risk-free, E(R)=7%, σ=10%."},{"id":"E03-02","los_ids":["CFA26-09-01-LOS03"],"problem":"rf=2%, P expected=10%, σ=16%; khách hàng chọn y=1,25.","solution_steps":["Expected combined=2%+1,25×(10%−2%)=12%.","Volatility=1,25×16%=20%.","Y>1 nghĩa là vay 25% vốn ban đầu để mua tổng 125% P trong giả định cho vay/vay như nhau."],"answer":"E(R)=12%, σ=20%; phát sinh leverage 25%."},{"id":"E04-01","los_ids":["CFA26-09-01-LOS04"],"problem":"Lợi suất 2%, 4%, 6%; tính mean và sample sd.","solution_steps":["Mean=(2+4+6)/3=4%.","Độ lệch −2%,0,+2%; tổng bình phương theo đơn vị thập phân =0,0008.","Sample variance=0,0008/(3−1)=0,0004; sample sd=√0,0004=2%."],"answer":"Mean 4%; sample standard deviation 2%."},{"id":"E04-02","los_ids":["CFA26-09-01-LOS04"],"problem":"X=[1%,2%,3%], Y=[3%,2%,1%]. Tính correlation.","solution_steps":["Mỗi chuỗi mean=2%.","X và Y có deviations đối dấu; sample covariance=(-1×1+0−1×1)/2 = −1 (điểm %)^2.","Sample variance mỗi chuỗi=1 (điểm %)^2; correlation=−1/√(1×1)=−1."],"answer":"ρ=−1, negative perfect linear correlation."},{"id":"E05-01","los_ids":["CFA26-09-01-LOS05"],"problem":"wA=60%, wB=40%, σA=20%, σB=10%, ρ=0,25. Tính σp.","solution_steps":["Variance = (0,6²×0,2²)+(0,4²×0,1²)+2×0,6×0,4×0,2×0,1×0,25.","=0,0144+0,0016+0,0024=0,0184.","σp=√0,0184=13,5647%."],"answer":"σp≈13,56%, không phải 0,6×20%+0,4×10%=16%."},{"id":"E05-02","los_ids":["CFA26-09-01-LOS05"],"problem":"Hai tài sản 50/50, σ đều 10%; ρ=−1; tính σp.","solution_steps":["Variance =0,25×0,01+0,25×0,01+2×0,5×0,5×0,01×(−1)=0.","σp=0 với weights/volatilities cân đối, trong mô hình tương quan hoàn hảo âm.","Thực tế tương quan −1 lâu dài hiếm."],"answer":"σp=0% theo giả định đặc biệt của đề."},{"id":"E06-01","los_ids":["CFA26-09-01-LOS06"],"problem":"A và B đều σ=20%, tỷ trọng 50/50; so σ khi ρ=1 với ρ=0.","solution_steps":["Nếu ρ=1, variance=0,04, σp=20%.","Nếu ρ=0, variance=0,25×0,04+0,25×0,04=0,02, σp=14,142%.","Diversification giảm σ khoảng 5,86 điểm %, dù rủi ro còn dương."],"answer":"σp giảm từ 20% xuống ≈14,14% khi correlation từ 1 xuống 0."},{"id":"E06-02","los_ids":["CFA26-09-01-LOS06"],"problem":"Danh mục 100 cổ phiếu cùng ngành dầu khí so với 20 cổ phiếu nhiều ngành.","solution_steps":["Số mã 100 lớn hơn nhưng có thể cùng chịu oil-price factor.","Danh mục 20 mã nhiều ngành có thể tương quan chung thấp hơn nếu các exposures thực sự khác nhau.","Cần kiểm tra covariance matrix và factor exposure, không xếp hạng theo số mã đơn thuần."],"answer":"Không thể khẳng định danh mục 100 mã có diversification tốt hơn."},{"id":"E07-01","los_ids":["CFA26-09-01-LOS07"],"problem":"Có A: E=5%, σ=10%; B: E=7%, σ=10%. A có hiệu quả không?","solution_steps":["Ở cùng σ=10%, B có E cao hơn 2 điểm %.","A bị dominated; không nằm trên efficient frontier nếu B khả thi.","Không cần biết danh mục khác để loại A."],"answer":"A không hiệu quả theo mean-variance dominance."},{"id":"E07-02","los_ids":["CFA26-09-01-LOS07"],"problem":"GMVP E=6%, σ=8%; portfolio C E=9%, σ=12%; portfolio D E=4%, σ=12%.","solution_steps":["GMVP có σ nhỏ nhất (8%).","C có E=9% với cùng σ=12% như D; C dominates D.","Nhánh phía trên GMVP có thể chứa C; D thuộc nhánh kém hiệu quả."],"answer":"D không hiệu quả; GMVP là mốc volatility thấp nhất."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-01-LOS01"],"stem":"Người cần chi trả tiền trong 2 tháng nên ưu tiên đặc điểm nào?","options":["Lợi suất cổ phiếu lịch sử cao nhất","Thanh khoản và an toàn danh nghĩa phù hợp nghĩa vụ","Mức đòn bẩy cao để tăng lợi suất"],"correct_option":1,"explanation":"Nghĩa vụ ngắn hạn cần công cụ có thể chuyển thành tiền đúng hạn, ít biến động giá; mức lợi suất kỳ vọng không bảo đảm hiện thực hóa."},{"id":"Q01-02","los_ids":["CFA26-09-01-LOS01"],"stem":"Tài sản thay thế được định giá ít thường xuyên có thể có tương quan công bố thấp vì nguyên nhân nào?","options":["Tài sản hoàn toàn không có rủi ro","Rủi ro tiền tệ tự triệt tiêu","Giá trị được làm mượt theo kỳ định giá"],"correct_option":2,"explanation":"Appraisal smoothing làm độ biến động và tương quan đo lường thấp hơn tính kinh tế thực; không nên tự động coi là đa dạng hóa mạnh."},{"id":"Q01-03","los_ids":["CFA26-09-01-LOS01"],"stem":"Lãi suất danh nghĩa 4% và lạm phát 3%, lợi suất thực gần nhất?","options":["0,97%","7%","4%"],"correct_option":0,"explanation":"Theo Fisher chính xác r_real=1,04/1,03−1≈0,97%; trừ trực tiếp cho gần 1%. Hai lựa chọn 7% và 4% lần lượt nhầm phép cộng tỷ lệ và nhầm lãi danh nghĩa với lãi thực."},{"id":"Q02-01","los_ids":["CFA26-09-01-LOS02"],"stem":"Với E(R) và σ không đổi, A tăng thì U thay đổi thế nào?","options":["Tăng","Giảm","Không đổi"],"correct_option":1,"explanation":"U=E(R)−0,5Aσ²; A tăng làm chi phí phạt rủi ro lớn hơn nếu σ>0. Các lựa chọn tăng hay không đổi bỏ qua tác động của hệ số A lên hình phạt variance."},{"id":"Q02-02","los_ids":["CFA26-09-01-LOS02"],"stem":"E(R)=10%, σ=20%, A=3; U?","options":["10%","16%","4%"],"correct_option":2,"explanation":"U=0,10−0,5×3×0,2²=0,04=4%. Không chọn 10% vì bỏ qua phần phạt rủi ro; 16% là phép cộng trái dấu của penalty."},{"id":"Q02-03","los_ids":["CFA26-09-01-LOS02"],"stem":"Risk capacity được phản ánh tốt nhất qua yếu tố nào?","options":["Quy mô tài sản so với nghĩa vụ cần thanh toán","Sở thích đánh cược cá nhân","Điểm số tự tin của nhà đầu tư"],"correct_option":0,"explanation":"Risk capacity là điều kiện tài chính khách quan; nó khác willingness hay khuynh hướng chấp nhận biến động."},{"id":"Q03-01","los_ids":["CFA26-09-01-LOS03"],"stem":"Slope CAL được tính bằng?","options":["E(Rp)/σp","[E(Rp)−rf]/σp","rf/σp"],"correct_option":1,"explanation":"Slope biểu thị excess return trên mỗi đơn vị total risk của risky portfolio; chính là Sharpe của P."},{"id":"Q03-02","los_ids":["CFA26-09-01-LOS03"],"stem":"rf=3%, E(Rp)=11%, σp=20%, A=4; y*?","options":["2,0","1,0","0,5"],"correct_option":2,"explanation":"y* =0,08/(4×0,20²)=0,5; phần còn lại ở risk-free. Tỷ trọng 2,0 là nhầm lấy mẫu số/tử số; y=1,0 không tối đa hóa utility với A=4."},{"id":"Q03-03","los_ids":["CFA26-09-01-LOS03"],"stem":"Khi y>1 trên CAL thì nhà đầu tư thường đang?","options":["Vay để tăng vị thế risky portfolio","Chỉ giữ cash","Hạ tỷ trọng risky asset dưới 100%"],"correct_option":0,"explanation":"Trong CAL chuẩn, y>1 được tài trợ bằng vị thế negative risk-free asset (borrowing)."},{"id":"Q04-01","los_ids":["CFA26-09-01-LOS04"],"stem":"Variance tính trên một mẫu quan sát lịch sử có mẫu số?","options":["n","n−1","n+1"],"correct_option":1,"explanation":"Sample variance dùng n−1 (Bessel correction), trừ khi đề xác định là population variance."},{"id":"Q04-02","los_ids":["CFA26-09-01-LOS04"],"stem":"X và Y có covariance âm; điều nào đúng?","options":["Tất cả lợi suất X âm","Phải có quan hệ nhân quả","Có xu hướng biến động ngược chiều tương đối mean"],"correct_option":2,"explanation":"Covariance âm cho biết tích deviations trung bình âm, không nói một tài sản phải có return âm."},{"id":"Q04-03","los_ids":["CFA26-09-01-LOS04"],"stem":"Correlation có thể là?","options":["−0,8","−1,5","1,2"],"correct_option":0,"explanation":"Correlation được chuẩn hóa, nằm trong đoạn −1 đến 1. Các số ngoài khoảng này vi phạm giới hạn của hệ số tương quan Pearson."},{"id":"Q05-01","los_ids":["CFA26-09-01-LOS05"],"stem":"σA=20%, σB=10%, wA=60%, wB=40%, ρ=0,25; σp gần nhất?","options":["16,0%","13,56%","19,5%"],"correct_option":1,"explanation":"Dùng variance tổng 0,0184 rồi căn = 13,56%; weighted average sd chỉ chính xác nếu ρ=1 cùng hướng."},{"id":"Q05-02","los_ids":["CFA26-09-01-LOS05"],"stem":"Giữ hai tỷ trọng đều dương, khi correlation giảm thì portfolio variance?","options":["Luôn tăng","Không thay đổi","Thường giảm"],"correct_option":2,"explanation":"Cross term 2wAwBσAσBρ giảm theo ρ khi weights cùng dương. “Luôn tăng” trái dấu của covariance term; “không đổi” bỏ qua hệ số ρ trong variance."},{"id":"Q05-03","los_ids":["CFA26-09-01-LOS05"],"stem":"Portfolio standard deviation bằng?","options":["Căn bậc hai của portfolio variance","Variance chia 2","Weighted average covariance"],"correct_option":0,"explanation":"Độ lệch chuẩn là square root của phương sai; đơn vị trở về % return. Variance chia 2 hay bình quân covariance không trả lại đúng đơn vị rủi ro của portfolio."},{"id":"Q06-01","los_ids":["CFA26-09-01-LOS06"],"stem":"Tác dụng đa dạng hóa cao nhất khi?","options":["Hai tài sản ρ=+1","Hai tài sản ρ=−1 và tỷ trọng phù hợp","Hai tài sản cùng ngành, cùng beta"],"correct_option":1,"explanation":"Perfect negative correlation cho khả năng triệt tiêu variance với tỷ trọng thích hợp, khác tương quan 0."},{"id":"Q06-02","los_ids":["CFA26-09-01-LOS06"],"stem":"Tăng số cổ phiếu từ 100 lên 101 thường giảm rủi ro riêng lẻ như thế nào?","options":["Giảm mạnh hơn từ 1 lên 2","Không bao giờ giảm","Giảm cận biên nhỏ hơn so với giai đoạn đầu"],"correct_option":2,"explanation":"Diminishing marginal benefit of diversification khi rủi ro riêng lẻ đã được san bớt."},{"id":"Q06-03","los_ids":["CFA26-09-01-LOS06"],"stem":"Rủi ro nào không bị loại bỏ bởi nắm nhiều cổ phiếu?","options":["Cú sốc lãi suất chung ảnh hưởng toàn thị trường","Một công ty bị mất CEO","Một công ty lỗi sản xuất"],"correct_option":0,"explanation":"Marketwide systematic risk tác động nhiều cổ phiếu cùng lúc và không thể đa dạng hóa hoàn toàn."},{"id":"Q07-01","los_ids":["CFA26-09-01-LOS07"],"stem":"GMVP là danh mục có?","options":["Beta bằng 1","Phương sai nhỏ nhất trong tập danh mục khả thi","Lợi suất kỳ vọng lớn nhất"],"correct_option":1,"explanation":"Global minimum-variance portfolio tối thiểu hóa toàn bộ variance, không tối đa hóa return."},{"id":"Q07-02","los_ids":["CFA26-09-01-LOS07"],"stem":"Nhánh minimum-variance frontier nào hiệu quả?","options":["Nhánh dưới GMVP","Cả hai luôn hiệu quả","Nhánh trên GMVP"],"correct_option":2,"explanation":"Ở cùng volatility, nhánh trên có expected return cao hơn nhánh dưới; chỉ nhánh trên là efficient."},{"id":"Q07-03","los_ids":["CFA26-09-01-LOS07"],"stem":"Danh mục A và B cùng σ=12%, E(A)=5%, E(B)=8%; chọn theo mean-variance efficiency?","options":["B","Cả hai","A"],"correct_option":0,"explanation":"B có expected return cao hơn trong cùng total risk, nên A bị dominated. A không thể là lựa chọn hiệu quả khi có danh mục B cùng σ nhưng expected return cao hơn."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-01-LOS01"],"front":"Lợi suất, rủi ro và thanh khoản là ba tiêu chí — giải thích bản chất?","back":"Trong xây dựng danh mục phải xét đồng thời lợi suất kỳ vọng, độ phân tán lợi suất, khả năng bán tài sản mà không làm giảm giá mạnh, lạm phát và kỳ hạn đầu tư. Lợi suất lịch sử cao không bảo đảm lợi suất kỳ vọng cao ở kỳ tới; so sánh cần nhất quán về loại tiền, kỳ và điều chỉnh lạm phát."},{"id":"C01-02","los_ids":["CFA26-09-01-LOS01"],"front":"Tiền mặt và công cụ ngắn hạn — giải thích bản chất?","back":"Cash equivalents và tín phiếu ngắn hạn thường có biến động giá thấp, khả năng thanh khoản cao; rủi ro tái đầu tư và rủi ro sức mua vẫn tồn tại. Nhà đầu tư có nghĩa vụ chi trả ngắn hạn không nên chỉ nhìn lợi suất cao của cổ phiếu."},{"id":"C01-03","los_ids":["CFA26-09-01-LOS01"],"front":"Trái phiếu và cổ phiếu — giải thích bản chất?","back":"Trái phiếu tạo dòng tiền hợp đồng, chịu duration, credit spread và default risk; cổ phiếu là quyền hưởng phần còn lại, lợi suất dài hạn biến động lớn, phụ thuộc lợi nhuận, định giá và tăng trưởng. Cổ phiếu có thể tạo lợi suất cao trong dài hạn nhưng tổn thất một năm có thể rất lớn."},{"id":"C02-01","los_ids":["CFA26-09-01-LOS02"],"front":"Risk aversion và mức đền bù rủi ro — giải thích bản chất?","back":"Risk-averse investor yêu cầu lợi suất kỳ vọng tăng khi chấp nhận biến động cao hơn. Risk-neutral chỉ quan tâm lợi suất kỳ vọng, còn risk-seeking có thể thích phân phối rủi ro hơn ở cùng kỳ vọng. Không nên đánh đồng risk tolerance với việc thích sản phẩm có coupon cao."},{"id":"C02-02","los_ids":["CFA26-09-01-LOS02"],"front":"Hàm hữu dụng mean-variance — giải thích bản chất?","back":"Một biểu diễn phổ biến là U=E(R)−0,5Aσ², trong đó A>0 biểu thị mức độ ghét rủi ro. Hai danh mục lợi suất kỳ vọng bằng nhau thì danh mục có σ nhỏ hơn cho U cao hơn; với cùng σ, danh mục E(R) lớn hơn cho U cao hơn."},{"id":"C02-03","los_ids":["CFA26-09-01-LOS02"],"front":"Đường bàng quan — giải thích bản chất?","back":"Indifference curve nối các tổ hợp E(R), σ có cùng U; đường dốc lên với người ghét rủi ro. A lớn đòi hỏi lợi suất bù đắp tăng nhanh hơn khi σ tăng; trên đồ thị E(R)−σ, investor rất ngại rủi ro có đường bàng quan dốc hơn."},{"id":"C03-01","los_ids":["CFA26-09-01-LOS03"],"front":"Capital allocation line — giải thích bản chất?","back":"CAL gồm các tổ hợp phân bổ giữa risk-free asset và một risky portfolio P: điểm y=0 chỉ giữ tài sản phi rủi ro, y=1 giữ 100% P, y>1 vay theo lãi suất giả định để mua thêm P, y<0 thể hiện short risky portfolio. Đường CAL thẳng nếu r_f, E(Rp) và σp không đổi."},{"id":"C03-02","los_ids":["CFA26-09-01-LOS03"],"front":"Hệ số Sharpe và độ dốc CAL — giải thích bản chất?","back":"Slope của CAL là (E(Rp)−r_f)/σp. Trong tập danh mục rủi ro khả thi, CAL cao nhất tiếp xúc efficient frontier tại tangency portfolio (nếu giả định vay/cho vay risk-free cùng lãi suất). Nhà đầu tư với A khác nhau chọn y khác nhau trên cùng CAL tốt nhất."},{"id":"C03-03","los_ids":["CFA26-09-01-LOS03"],"front":"Điểm tiếp xúc và đường bàng quan — giải thích bản chất?","back":"Danh mục tối ưu của nhà đầu tư là điểm tiếp xúc giữa CAL hiệu quả và đường bàng quan cao nhất có thể đạt. Risk aversion càng lớn thì tỷ trọng vốn trong danh mục rủi ro càng nhỏ, các yếu tố còn lại giữ nguyên."},{"id":"C04-01","los_ids":["CFA26-09-01-LOS04"],"front":"Arithmetic mean và weighted mean — giải thích bản chất?","back":"Lợi suất trung bình lịch sử theo mẫu là tổng lợi suất chia số quan sát, dùng cho ước tính kỳ vọng một kỳ nếu các kỳ tương đồng. Mean có trọng số theo xác suất là Σp_iR_i, không dùng tỷ trọng tài sản w khi mục tiêu là mean của cùng một tài sản theo thời gian."},{"id":"C04-02","los_ids":["CFA26-09-01-LOS04"],"front":"Sample variance và sample standard deviation — giải thích bản chất?","back":"Khi dữ liệu là mẫu gồm n lợi suất lịch sử, phương sai mẫu s²=Σ(R_i−Rbar)²/(n−1), standard deviation s=√s². Phương sai tổng thể có mẫu số N; không trộn hai quy ước trong cùng bài."},{"id":"C04-03","los_ids":["CFA26-09-01-LOS04"],"front":"Covariance và correlation — giải thích bản chất?","back":"Sample covariance s_xy=Σ[(x_i−xbar)(y_i−ybar)]/(n−1); sample correlation ρ_xy=s_xy/(s_xs_y). ρ nằm trong [−1,1]; covariance phụ thuộc đơn vị và quy mô volatility, correlation không có đơn vị."},{"id":"C05-01","los_ids":["CFA26-09-01-LOS05"],"front":"Return và variance danh mục hai tài sản — giải thích bản chất?","back":"E(Rp)=wA E(RA)+wB E(RB). Variance phụ thuộc cả volatility riêng và covariance: σp²=wA²σA²+wB²σB²+2wAwBσAσBρAB. Không được lấy weighted average σ trừ trường hợp tương quan đặc biệt."},{"id":"C05-02","los_ids":["CFA26-09-01-LOS05"],"front":"Đa tài sản và ma trận covariance — giải thích bản chất?","back":"Với n tài sản, σp²=Σ_i Σ_j w_iw_jCov(Ri,Rj)=wᵀΣw. Ma trận covariance phải đối xứng, phương sai trên đường chéo và nonnegative semidefinite; lỗi covariance không nhất quán có thể cho variance âm phi lý."},{"id":"C05-03","los_ids":["CFA26-09-01-LOS05"],"front":"Correlation làm thay đổi σp — giải thích bản chất?","back":"Giữ σA,σB và weights cố định, ρ giảm làm portfolio variance giảm khi weights cùng dấu. Ở short position (trọng số âm), quan hệ với ρ cần xem dấu của wAwB."},{"id":"C06-01","los_ids":["CFA26-09-01-LOS06"],"front":"Lợi ích từ correlation dưới +1 — giải thích bản chất?","back":"Khi nhiều tài sản không hoàn toàn đồng biến, gains và losses có thể bù nhau một phần; σp thấp hơn bình quân có trọng số σ khi weights không âm. Correlation 0 không đồng nghĩa không rủi ro, và hoàn toàn âm −1 có thể loại bỏ rủi ro với tỷ trọng thích hợp."},{"id":"C06-02","los_ids":["CFA26-09-01-LOS06"],"front":"Rủi ro hệ thống và riêng lẻ — giải thích bản chất?","back":"Khi tăng số tài sản, rủi ro idiosyncratic giảm nhưng macro/systematic risk không biến mất. Không thể loại bỏ risk premium từ những cú sốc thị trường chung chỉ bằng cách thêm cổ phiếu cùng beta."},{"id":"C06-03","los_ids":["CFA26-09-01-LOS06"],"front":"Diminishing marginal benefit — giải thích bản chất?","back":"Khi từ 1 lên 5 tài sản thường giảm mạnh rủi ro riêng lẻ hơn từ 100 lên 104 tài sản, nếu các khoản đầu tư đa dạng tương đối và không tập trung vào cùng nhân tố."},{"id":"C07-01","los_ids":["CFA26-09-01-LOS07"],"front":"Tập hợp danh mục khả thi — giải thích bản chất?","back":"Feasible set gồm mọi phối hợp tài sản với các mức E(R), σ; tập hợp hình dạng khác nhau tùy short selling, constraints và ma trận covariance. Minimum-variance frontier là biên bên trái: phương sai thấp nhất ở mỗi mức lợi suất kỳ vọng."},{"id":"C07-02","los_ids":["CFA26-09-01-LOS07"],"front":"Global minimum-variance portfolio — giải thích bản chất?","back":"GMVP là điểm trên minimum-variance frontier có σ nhỏ nhất trên toàn bộ danh mục khả thi. Không nhất thiết là danh mục lợi suất cao nhất; vị trí GMVP phân chia nhánh hữu hiệu và không hữu hiệu."},{"id":"C07-03","los_ids":["CFA26-09-01-LOS07"],"front":"Efficient frontier của risky assets — giải thích bản chất?","back":"Nhánh phía trên GMVP là mean-variance efficient frontier: không có danh mục khác cùng σ nhưng E(R) cao hơn, hoặc cùng E(R) mà σ thấp hơn. Nhánh dưới GMVP bị dominated."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_source_PDFs"},{"module_id":"CFA26-09-02","title":"Portfolio Risk and Return: Part II","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[71,130],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[84,106],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[50,83],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-02-LOS01","learning_goal_vi":"Mô tả ý nghĩa kết hợp risk-free asset với một risky portfolio.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01","F01-02"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":75},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":85},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":52}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS02","learning_goal_vi":"Giải thích capital allocation line (CAL) và capital market line (CML).","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04"],"formula_ids":["F02-01","F02-02"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":79},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":86},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":53}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS03","learning_goal_vi":"Phân biệt systematic và nonsystematic risk và vì sao không được thưởng cho rủi ro riêng lẻ.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":85},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":88},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":57}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS04","learning_goal_vi":"Giải thích return-generating models, bao gồm market model, và mục đích sử dụng.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05"],"formula_ids":["F04-01","F04-02"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":88},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":90},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":59}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS05","learning_goal_vi":"Tính và diễn giải beta.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S05-01","S05-02","S05-03","S05-04","S05-05"],"formula_ids":["F05-01","F05-02","F05-03"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":91},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":91},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":61}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS06","learning_goal_vi":"Giải thích CAPM, giả định và security market line (SML).","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S06-01","S06-02","S06-03","S06-04","S06-05"],"formula_ids":["F06-01","F06-02"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":97},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":94},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":64}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS07","learning_goal_vi":"Tính và diễn giải expected return của một tài sản theo CAPM.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S07-01","S07-02","S07-03","S07-04","S07-05"],"formula_ids":["F07-01","F07-02"],"example_ids":["E07-01","E07-02"],"question_ids":["Q07-01","Q07-02","Q07-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":98},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":94},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":66}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS08","learning_goal_vi":"Mô tả và minh họa ứng dụng của CAPM và SML.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S08-01","S08-02","S08-03","S08-04","S08-05"],"formula_ids":["F08-01","F08-02"],"example_ids":["E08-01","E08-02"],"question_ids":["Q08-01","Q08-02","Q08-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":100},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":98},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":68}},"missing_items":[]},{"los_id":"CFA26-09-02-LOS09","learning_goal_vi":"Tính và diễn giải Sharpe, Treynor, M² và Jensen alpha.","status":"targeted_CFAI_Kaplan_SAPP_and_sample_independent_math_QA_pass","competency_criteria":["Nội dung diễn giải theo LOS CFA Institute 2026","Đối chiếu những phần liên quan trong Kaplan, SAPP","Ví dụ, công thức và điều kiện ứng dụng riêng theo LOS","Câu hỏi tự viết có giải thích đáp án","Kiểm tra phép tính độc lập và hiển thị website"],"concept_ids":["S09-01","S09-02","S09-03","S09-04","S09-05","S09-06"],"formula_ids":["F09-01","F09-02","F09-03","F09-04"],"example_ids":["E09-01","E09-02"],"question_ids":["Q09-01","Q09-02","Q09-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":107},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":100},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":71}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-02-LOS01"],"heading_vi":"Điều kiện của risk-free asset","body_vi":"Risk-free asset trong mô hình có lợi suất chắc chắn cùng thời hạn đầu tư và đơn vị tiền tệ với khoản phân bổ; vì vậy σrf=0 và covariance với risky asset bằng 0. Trái phiếu chính phủ dài hạn vẫn có market-price risk nếu bán trước kỳ hạn."},{"id":"S01-02","los_ids":["CFA26-09-02-LOS01"],"heading_vi":"Biến đổi phân phối lợi suất","body_vi":"Nếu dành tỷ trọng y vào risky portfolio và 1−y vào risk-free, E(Rc)=rf+y(E(Rp)−rf), σc=|y|σp. Tỷ trọng y nhỏ làm giảm total volatility và expected excess return tỷ lệ thuận trong giả định mô hình."},{"id":"S01-03","los_ids":["CFA26-09-02-LOS01"],"heading_vi":"Lending, borrowing và leverage","body_vi":"Với 0≤y≤1 nhà đầu tư trộn cash và risky fund; y>1 nghĩa là vay bằng negative risk-free weight để giữ vị thế risky lớn hơn vốn tự có. Vay ngoài thực tế có lãi suất cao hơn rf và margin constraints nên đường cơ hội có thể gãy khúc."},{"id":"S01-04","los_ids":["CFA26-09-02-LOS01"],"heading_vi":"Không nhầm risk-free với default-free","body_vi":"Rủi ro lãi suất, lạm phát và tiền tệ khiến công cụ được coi risk-free ở khía cạnh danh nghĩa hoặc một kỳ chưa chắc an toàn về real return. Lựa chọn proxy cần phù hợp kỳ nắm giữ."},{"id":"S02-01","los_ids":["CFA26-09-02-LOS02"],"heading_vi":"CAL cho từng risky portfolio","body_vi":"CAL vẽ các phối hợp expected return và standard deviation từ một risky portfolio P với risk-free asset; trục x là total risk σ, trục y E(R). Mỗi P có một CAL riêng với slope Sharpe(P)."},{"id":"S02-02","los_ids":["CFA26-09-02-LOS02"],"heading_vi":"CML là CAL đặc biệt","body_vi":"Trong thế giới CAPM cân bằng và giả định đồng nhất, market portfolio M là tangency risky portfolio; CAL qua rf và M được gọi Capital Market Line (CML). Tài sản hoặc danh mục không efficient nằm ngoài CML, nên không tính E(Ri) theo CML cho cổ phiếu riêng lẻ."},{"id":"S02-03","los_ids":["CFA26-09-02-LOS02"],"heading_vi":"Lending và borrowing dọc CML","body_vi":"Điểm giữa rf và M là kết hợp cash với market portfolio. Điểm phía phải M là leverage market portfolio; nếu lãi vay khác lãi cho vay, cơ hội đầu tư không còn đường thẳng duy nhất và CML lý thuyết không khớp."},{"id":"S02-04","los_ids":["CFA26-09-02-LOS02"],"heading_vi":"Đối chiếu CML với SML","body_vi":"CML dùng σ (total risk) cho efficient portfolios, slope [E(Rm)−rf]/σm. SML dùng beta (systematic risk) và áp dụng cho mọi tài sản được định giá trong CAPM. Không lấy sigma đưa vào phương trình SML."},{"id":"S03-01","los_ids":["CFA26-09-02-LOS03"],"heading_vi":"Systematic risk","body_vi":"Market risk xuất phát từ những nhân tố tác động diện rộng như tăng trưởng, lạm phát và monetary policy. Một danh mục đa dạng hóa vẫn chịu các biến động chung; CAPM định giá phần này qua beta."},{"id":"S03-02","los_ids":["CFA26-09-02-LOS03"],"heading_vi":"Nonsystematic risk","body_vi":"Company-specific hoặc sector-specific shocks như thay đổi CEO, product recall, lawsuit có thể giảm qua việc kết hợp nhiều khoản đầu tư ít tương quan. Khi số lượng tài sản đa dạng tăng lên, tổng rủi ro giảm nhưng tiến về mức systematic risk thay vì 0."},{"id":"S03-03","los_ids":["CFA26-09-02-LOS03"],"heading_vi":"Tại sao không có premium cho unsystematic risk","body_vi":"Nhà đầu tư có thể loại bỏ phần lớn idiosyncratic risk với chi phí thấp bằng đa dạng hóa; thị trường cân bằng không phải trả thêm expected return chỉ vì nhà đầu tư tự nguyện giữ danh mục tập trung."},{"id":"S03-04","los_ids":["CFA26-09-02-LOS03"],"heading_vi":"Total risk decomposition","body_vi":"Trong market model, Var(Ri)=βi²Var(Rm)+Var(εi) nếu residual không tương quan với market. Term đầu là market-related systematic variance; term sau là residual firm-specific variance."},{"id":"S03-05","los_ids":["CFA26-09-02-LOS03"],"heading_vi":"Bẫy kiểm tra","body_vi":"Total σ cao không nhất thiết beta cao; cổ phiếu biotech có thể rất biến động vì trial result nhưng beta thấp. Đề hỏi compensated risk trong CAPM thì chọn systematic/beta, không chọn tổng volatility."},{"id":"S04-01","los_ids":["CFA26-09-02-LOS04"],"heading_vi":"Return-generating models là gì","body_vi":"Các mô hình quy lợi suất của chứng khoán về các nhân tố thống kê, kinh tế vĩ mô hoặc đặc trưng cơ bản. Mô hình giúp ước lượng exposure, scenario analysis, attribution và risk management, nhưng kết quả phụ thuộc nhân tố chọn, phương pháp ước lượng và dữ liệu."},{"id":"S04-02","los_ids":["CFA26-09-02-LOS04"],"heading_vi":"Market model","body_vi":"Một mô hình thời gian: R_i=α_i+β_iR_M+ε_i. β_i là slope tuyến tính giữa security return và market return, α intercept, ε specific return không giải thích bởi market. Market model là mô hình thực nghiệm, không tự đồng nhất với expected CAPM pricing equation."},{"id":"S04-03","los_ids":["CFA26-09-02-LOS04"],"heading_vi":"Macroeconomic và fundamental factor models","body_vi":"Macro factors có thể gồm inflation surprise, GDP growth, interest-rate shock; fundamental factors gồm size, value, profitability. Exposure và factor returns có thể mang các đơn vị khác nhau; cần xác định ý nghĩa của hệ số để giải thích."},{"id":"S04-04","los_ids":["CFA26-09-02-LOS04"],"heading_vi":"Statistical factor models","body_vi":"Dựa trên covariance và công cụ thống kê như PCA để rút gọn nhân tố tương quan, thường chưa có diễn giải kinh tế rõ bằng macro model. Số nhân tố và sample period ảnh hưởng kết quả."},{"id":"S04-05","los_ids":["CFA26-09-02-LOS04"],"heading_vi":"Các giới hạn","body_vi":"Overfitting, look-ahead bias, regime change, correlation giữa factors và estimation error có thể làm mô hình dự báo sai. Mô hình nhiều nhân tố không bảo đảm cổ phiếu là khoản đầu tư tốt."},{"id":"S05-01","los_ids":["CFA26-09-02-LOS05"],"heading_vi":"Beta đo market sensitivity","body_vi":"β_i=Cov(R_i,R_M)/Var(R_M), là slope regression market model. Beta=1: biến động trung bình cùng chiều với market theo slope khoảng 1; beta>1 nhạy hơn; beta<0 thường biến động trái chiều với market."},{"id":"S05-02","los_ids":["CFA26-09-02-LOS05"],"heading_vi":"Beta không bằng volatility","body_vi":"Cổ phiếu có β=1,5 không nhất thiết có σ cao gấp 1,5 thị trường vì còn residual risk. Beta có thể tính bằng ρ_iM(σ_i/σ_M) khi standard deviations dương. Hai cổ phiếu có cùng beta vẫn có thể khác biệt rất lớn về total risk nếu mức độ nhiễu firm-specific khác nhau."},{"id":"S05-03","los_ids":["CFA26-09-02-LOS05"],"heading_vi":"Beta danh mục","body_vi":"βp=Σw_iβ_i nếu trọng số dollar và beta cùng market benchmark. Với risk-free β=0, mix 50% stock β=1,2 và 50% risk-free cho βp=0,6. Với tỷ trọng âm do bán khống, portfolio beta có thể âm hoặc vượt beta của tất cả các vị thế long riêng lẻ."},{"id":"S05-04","los_ids":["CFA26-09-02-LOS05"],"heading_vi":"Hồi quy và lựa chọn dữ liệu","body_vi":"Historical beta nhạy với benchmark, frequency, period, outliers và thin trading; adjusted beta có thể shrink về 1 nhưng phải nêu giả định. Dữ liệu ít hoặc correlation yếu làm hệ số ước lượng không chắc chắn."},{"id":"S05-05","los_ids":["CFA26-09-02-LOS05"],"heading_vi":"Ý nghĩa thực tế","body_vi":"Beta đo relative market exposure, không phải khả năng mất toàn bộ vốn. Negative beta có thể giúp hedge market nhưng hệ số có thể đổi theo chế độ thị trường. Beta bằng 0 không đồng nghĩa asset không có rủi ro hoặc lợi nhuận luôn bằng risk-free trong từng giai đoạn quan sát."},{"id":"S06-01","los_ids":["CFA26-09-02-LOS06"],"heading_vi":"CAPM và market risk premium","body_vi":"CAPM liên hệ expected required return với exposure to market portfolio: E(R_i)=r_f+β_i[E(R_M)−r_f]. Market premium là E(RM)−rf, không phải observed market return trừ market return kỳ trước."},{"id":"S06-02","los_ids":["CFA26-09-02-LOS06"],"heading_vi":"Ý nghĩa SML","body_vi":"SML đặt β trên trục x và required expected return trên trục y. SML intercept r_f tại β=0, slope market premium. Security nằm trên SML được định giá phù hợp CAPM, security nằm trên đường cần so với investor expected return để đánh giá alpha."},{"id":"S06-03","los_ids":["CFA26-09-02-LOS06"],"heading_vi":"Các giả định điển hình","body_vi":"Nhà đầu tư tối đa hóa mean-variance utility một kỳ; kỳ vọng đồng nhất; tài sản phân chia, mua bán không ma sát; không có taxes/transaction costs; có thể vay và cho vay ở rf; thị trường cạnh tranh và cùng tập cơ hội."},{"id":"S06-04","los_ids":["CFA26-09-02-LOS06"],"heading_vi":"Market portfolio và diversification","body_vi":"Trong trạng thái cân bằng CAPM, tất cả nhà đầu tư giữ cùng risky market portfolio với các weights khác nhau nhờ trộn risk-free. Rủi ro không hệ thống có thể loại bỏ trong market portfolio, nên premium chỉ áp dụng systematic risk."},{"id":"S06-05","los_ids":["CFA26-09-02-LOS06"],"heading_vi":"Hạn chế sử dụng","body_vi":"Real-world proxies cho market portfolio không đầy đủ; historical beta và equity risk premium ước lượng sai; borrowing rate khác lending; returns không normal, tail risk tồn tại. Mô hình hữu ích làm benchmark nhưng không phải định luật dự báo chính xác từng cổ phiếu."},{"id":"S07-01","los_ids":["CFA26-09-02-LOS07"],"heading_vi":"Chọn đúng market premium","body_vi":"Lấy expected market return trừ đúng risk-free rate cùng kỳ, cùng currency. Đề có realized market return kỳ trước thì chưa đủ để làm expected premium nếu không chỉ định."},{"id":"S07-02","los_ids":["CFA26-09-02-LOS07"],"heading_vi":"Tính required return","body_vi":"Dùng β×market risk premium rồi cộng rf. Nếu beta âm và premium dương, required return thấp hơn rf; β>1 có required return cao hơn market theo CAPM. Lưu ý đây là mức return yêu cầu lý thuyết; actual realized return có thể thấp hoặc cao tùy diễn biến thị trường."},{"id":"S07-03","los_ids":["CFA26-09-02-LOS07"],"heading_vi":"Kiểm tra valuation so với forecast","body_vi":"Analyst forecast E(Ri) lớn hơn CAPM required return có positive expected alpha trong cùng mô hình và giả định; không tự động có arbitrage profit. Forecast không chắc chắn và beta có thể thay đổi."},{"id":"S07-04","los_ids":["CFA26-09-02-LOS07"],"heading_vi":"Reverse engineer beta hoặc premium","body_vi":"Nếu biết E(Ri), rf và market premium khác 0, beta implied=(E(Ri)−rf)/(E(RM)−rf). Có thể tìm implied market premium từ nhiều assets để kiểm tra consistency. Nếu premium bằng 0, công thức chia không hợp lệ và không thể suy ra implied beta bằng phép chia thông thường."},{"id":"S07-05","los_ids":["CFA26-09-02-LOS07"],"heading_vi":"Sai lầm đơn vị","body_vi":"Beta không có đơn vị; nếu rf=4% và premium=6%, β=1,4 thì 4%+1,4×6%=12,4%, không phải 4%+140%×6% viết tùy tiện. Cách chuẩn là giữ beta dạng hệ số thuần và các lãi suất cùng là %, hoặc chuyển tất cả lãi suất sang số thập phân."},{"id":"S08-01","los_ids":["CFA26-09-02-LOS08"],"heading_vi":"Cost of equity và discount rate","body_vi":"CAPM được dùng để ước lượng shareholders’ required return k_e trong định giá cổ phiếu/DCF và WACC. Beta nên phản ánh business/financial risk của khoản đầu tư, không dùng beta của công ty khác không tương đồng."},{"id":"S08-02","los_ids":["CFA26-09-02-LOS08"],"heading_vi":"Capital budgeting","body_vi":"Dự án có beta cao hơn hoạt động lõi cần required return/hurdle rate phù hợp, không nhất thiết dùng companywide WACC. Áp dụng dự án theo SML để xác định suất sinh lợi yêu cầu cho systematic risk."},{"id":"S08-03","los_ids":["CFA26-09-02-LOS08"],"heading_vi":"Security selection và alpha","body_vi":"So expected return analyst forecast với SML benchmark: above-SML (alpha dương) có thể hàm ý underpriced theo dự báo; below-SML (alpha âm) có thể hàm ý overpriced. Không đồng nghĩa chắc chắn có cơ hội chênh lệch giá phi rủi ro."},{"id":"S08-04","los_ids":["CFA26-09-02-LOS08"],"heading_vi":"Risk-adjusted performance","body_vi":"SML cung cấp benchmark return cho một danh mục thông qua β; Jensen alpha đo actual/expected excess performance so với benchmark. SML áp dụng mọi assets, khác CML chỉ cho efficient portfolios."},{"id":"S08-05","los_ids":["CFA26-09-02-LOS08"],"heading_vi":"Hạn chế triển khai","body_vi":"Beta historical có estimation error, project beta khó xác định; lựa chọn risk-free và market premium ảnh hưởng mạnh valuation. Không dùng alpha khi inputs chưa đồng nhất kỳ hoặc currency."},{"id":"S09-01","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"Sharpe ratio","body_vi":"Sharpe=(Rp−rf)/σp đo excess return trên total standard deviation, hữu ích khi so các danh mục không nhất thiết đã đa dạng hóa. Nếu σ=0 thì không định nghĩa; Sharpe âm cần thận trọng khi so với volatility."},{"id":"S09-02","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"Treynor ratio","body_vi":"Treynor=(Rp−rf)/βp đo excess return trên systematic risk; phù hợp hơn với fully diversified portfolios. Khi beta gần 0, bằng 0 hoặc âm, tỷ lệ khó diễn giải và xếp hạng có thể sai."},{"id":"S09-03","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"Jensen alpha","body_vi":"αp=Rp−[rf+βp(RM−rf)] đo chênh lệch return thực hiện/dự báo với CAPM benchmark trong cùng kỳ. Có thể khác forecast alpha dựa expected future return. Một Jensen alpha dương có thể phản ánh dự báo tốt, benchmark không phù hợp, beta ước lượng sai hoặc yếu tố may mắn."},{"id":"S09-04","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"M-squared measure","body_vi":"M² điều chỉnh portfolio excess return về độ biến động của market: M²=rf+Sharpe_p×σM (dạng return đã điều chỉnh); một số giáo trình gọi M² excess là [Sharpe_p−Sharpe_M]×σM. Cần đọc câu hỏi để biết muốn adjusted return hay chênh lệch so với market return."},{"id":"S09-05","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"So sánh có điều kiện","body_vi":"Sharpe dùng total risk nên phù hợp danh mục chưa đa dạng hóa; Treynor/Jensen dùng beta, đòi benchmark thích hợp. M² có cùng đơn vị % return, giúp trực quan so với market return sau điều chỉnh volatility."},{"id":"S09-06","los_ids":["CFA26-09-02-LOS09"],"heading_vi":"Sai lầm khi tính","body_vi":"Đảm bảo Rp, rf, RM cùng kỳ, σ là standard deviation chứ không phải variance, beta không nhân 100, và dùng realized vs expected theo đề. Không diễn giải Sharpe cao ở sample nhỏ như bảo đảm quản lý giỏi."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-02-LOS01"],"expression":"E(Rc)=rf+y(E(Rp)−rf)","variables":["y fraction invested in risky portfolio."],"assumptions":["Borrowing/lending rate identical in idealized model."]},{"id":"F01-02","los_ids":["CFA26-09-02-LOS01"],"expression":"σc=|y|σp","variables":["σrf=0 and cov=0."],"assumptions":["Same investment period; linear return assumptions."]},{"id":"F02-01","los_ids":["CFA26-09-02-LOS02"],"expression":"CAL: E(Rc)=rf+([E(Rp)−rf]/σp)σc","variables":["For nonnegative y, σc=yσp."],"assumptions":["One risky fund P, same risk-free borrowing/lending rate."]},{"id":"F02-02","los_ids":["CFA26-09-02-LOS02"],"expression":"CML: E(Rp)=rf+[E(RM)−rf]σp/σM","variables":["Only efficient portfolios on CML."],"assumptions":["Market portfolio is tangency fund in CAPM equilibrium."]},{"id":"F03-01","los_ids":["CFA26-09-02-LOS03"],"expression":"Var(Ri)=βi² Var(RM)+Var(εi)","variables":["Market model residual orthogonal to market return."],"assumptions":["Single-factor linear model; may not be exact in reality."]},{"id":"F04-01","los_ids":["CFA26-09-02-LOS04"],"expression":"Ri=αi+βi RM+εi","variables":["α intercept, β sensitivity, ε residual."],"assumptions":["Market model, not the CAPM expected-return relation."]},{"id":"F04-02","los_ids":["CFA26-09-02-LOS04"],"expression":"Ri=α+Σ bk Fk+ε","variables":["Fk returns/surprises of selected factors."],"assumptions":["Factor exposures estimated from suitable historical sample."]},{"id":"F05-01","los_ids":["CFA26-09-02-LOS05"],"expression":"βi=Cov(Ri,RM)/Var(RM)","variables":["Same sample period, Var(RM)>0."],"assumptions":["Slope of a market regression."]},{"id":"F05-02","los_ids":["CFA26-09-02-LOS05"],"expression":"βi=ρiM × σi/σM","variables":["Both standard deviations positive."],"assumptions":["Correlation and volatilities measured over same horizon."]},{"id":"F05-03","los_ids":["CFA26-09-02-LOS05"],"expression":"βp=Σ wiβi","variables":["Weights sum to 1 for fully invested portfolio."],"assumptions":["Same benchmark and currency."]},{"id":"F06-01","los_ids":["CFA26-09-02-LOS06"],"expression":"E(Ri)=rf+βi[E(RM)−rf]","variables":["β systematic risk; market premium from expected market return."],"assumptions":["CAPM assumptions as specified in reading."]},{"id":"F06-02","los_ids":["CFA26-09-02-LOS06"],"expression":"SML slope=E(RM)−rf","variables":["Horizontal axis β, not σ."],"assumptions":["Positive expected market premium for upward-sloping SML."]},{"id":"F07-01","los_ids":["CFA26-09-02-LOS07"],"expression":"Required return = rf+β×MRP","variables":["MRP=E(RM)−rf."],"assumptions":["Same currency/time horizon for inputs."]},{"id":"F07-02","los_ids":["CFA26-09-02-LOS07"],"expression":"β_implied=(E(Ri)−rf)/MRP","variables":["MRP nonzero."],"assumptions":["Interpret as CAPM-implied systematic exposure."]},{"id":"F08-01","los_ids":["CFA26-09-02-LOS08"],"expression":"Cost of equity ke=rf+βe[E(RM)−rf]","variables":["Equity beta as applicable to business/financial leverage."],"assumptions":["CAPM estimate, with estimated risk-free and premium."]},{"id":"F08-02","los_ids":["CFA26-09-02-LOS08"],"expression":"α_expected=E(Rforecast)−[rf+βMRP]","variables":["Compare like for like holding horizon."],"assumptions":["Forecast alpha, not realized arbitrage."]},{"id":"F09-01","los_ids":["CFA26-09-02-LOS09"],"expression":"Sharpe_p=(Rp−rf)/σp","variables":["Return and σ same time basis."],"assumptions":["σp>0."]},{"id":"F09-02","los_ids":["CFA26-09-02-LOS09"],"expression":"Treynor_p=(Rp−rf)/βp","variables":["Beta measured to benchmark."],"assumptions":["Most interpretable for diversified portfolio and positive nonzero β."]},{"id":"F09-03","los_ids":["CFA26-09-02-LOS09"],"expression":"Jensen alpha=Rp−[rf+βp(RM−rf)]","variables":["Use realized or expected as specified."],"assumptions":["Same performance horizon for inputs."]},{"id":"F09-04","los_ids":["CFA26-09-02-LOS09"],"expression":"M²_adjusted=rf+Sharpe_p σM","variables":["σM is market volatility."],"assumptions":["Some definitions use relative M² = adjusted return − RM."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-02-LOS01"],"problem":"rf=3%, P=11%, σp=18%, y=40%; tìm E(Rc), σc.","solution_steps":["E(Rc)=3%+0,4×8%=6,2%.","σc=0,4×18%=7,2%.","Lợi suất kỳ vọng cao hơn rf 3,2 điểm % vì nắm 40% risky."],"answer":"E(Rc)=6,2%; σc=7,2%."},{"id":"E01-02","los_ids":["CFA26-09-02-LOS01"],"problem":"rf=2%, P=10%, σp=15%, y=1,5.","solution_steps":["Đầu tư 150% P cần vay 50% vốn danh nghĩa.","E(Rc)=2%+1,5×8%=14%.","σc=1,5×15%=22,5% nếu không có margin/lãi vay chênh lệch."],"answer":"E(Rc)=14%; σc=22,5%, mức đòn bẩy cao."},{"id":"E02-01","los_ids":["CFA26-09-02-LOS02"],"problem":"rf=3%, Market E=9%, σM=15%; efficient portfolio σ=10%. Tính E theo CML.","solution_steps":["Market risk premium = 9%−3%=6%.","CML slope=6%/15%=0,4.","E(Rp)=3%+0,4×10%=7%."],"answer":"E(Rp)=7% nếu danh mục nằm trên CML."},{"id":"E02-02","los_ids":["CFA26-09-02-LOS02"],"problem":"Cổ phiếu riêng lẻ σ=25% nhưng beta=0,6. Có được dùng CML để tính return không?","solution_steps":["CML có điều kiện danh mục efficient và total risk, cổ phiếu riêng lẻ thường không nằm trên CML.","Nếu áp dụng CAPM/SML phải dùng β=0,6 cùng market risk premium.","Không suy ra expected return theo CML từ σ=25% cho security này."],"answer":"Dùng SML/CAPM với beta, không dùng CML cho một cổ phiếu tùy ý."},{"id":"E03-01","los_ids":["CFA26-09-02-LOS03"],"problem":"A và B cùng beta=1; A σ=40%, B σ=20%. CAPM dự báo return khác không?","solution_steps":["Cả hai cùng beta nên expected CAPM return bằng nhau với cùng rf và market premium.","Phần σ vượt trội của A có thể do residual specific variance.","Tập trung A không tạo thêm systematic premium trong CAPM."],"answer":"CAPM expected return như nhau nếu beta của A và B đều bằng 1."},{"id":"E03-02","los_ids":["CFA26-09-02-LOS03"],"problem":"Market σ=15%, beta stock=1,2; residual variance=0,04. Total variance?","solution_steps":["Systematic variance=1,2²×0,15²=0,0324.","Total variance=0,0324+0,04=0,0724.","Total σ=√0,0724≈26,91%; systematic variance không phải total σ."],"answer":"Total variance=0,0724; σ≈26,91%."},{"id":"E04-01","los_ids":["CFA26-09-02-LOS04"],"problem":"Market model α=1%, β=1,3; market return=5%, residual=−2%. Dự tính Ri.","solution_steps":["Market contribution =1,3×5%=6,5%.","Ri=1%+6,5%−2%=5,5%.","Residual −2% là khoản không được market factor giải thích."],"answer":"Mô hình cho Ri=5,5%."},{"id":"E04-02","los_ids":["CFA26-09-02-LOS04"],"problem":"Factor model có inflation-surprise shock=+1 điểm %, exposure −2%.","solution_steps":["Factor contribution=−2×(+1 điểm %) = −2 điểm % nếu hệ số được định nghĩa như vậy.","Phải cộng với intercept và contributions từ factors khác để ra total return.","Đơn vị factor cần thống nhất để tránh nhân 1 với 0,01 sai."],"answer":"Ri giảm 2 điểm % từ factor shock này, giữ các yếu tố khác không đổi."},{"id":"E05-01","los_ids":["CFA26-09-02-LOS05"],"problem":"Cov(Ri,RM)=0,024; Var(RM)=0,016. Beta?","solution_steps":["β=0,024/0,016=1,5.","Nếu market tăng 1 điểm %, phần market-linked expected movement xấp xỉ +1,5 điểm %, không chắc chắn do ε."],"answer":"β=1,5, độ nhạy với market cao hơn 1."},{"id":"E05-02","los_ids":["CFA26-09-02-LOS05"],"problem":"Danh mục 60% stock A beta=1,5 và 40% B beta=0,5; beta danh mục?","solution_steps":["βp=0,6×1,5+0,4×0,5=0,9+0,2=1,1.","Không lấy trọng số theo biến động riêng nếu câu hỏi hỏi portfolio beta."],"answer":"Portfolio beta bằng 1,10, cao hơn thị trường ở mức độ nhạy tuyến tính trong mô hình beta một nhân tố."},{"id":"E06-01","los_ids":["CFA26-09-02-LOS06"],"problem":"rf=3%, market expected=9%, beta stock=1,2. CAPM required return?","solution_steps":["Market premium=9%−3%=6%.","Required E(Ri)=3%+1,2×6%=10,2%.","Không dùng stock total sd làm beta."],"answer":"Required expected return 10,2%."},{"id":"E06-02","los_ids":["CFA26-09-02-LOS06"],"problem":"Security beta=0, required CAPM return?","solution_steps":["Theo CAPM, E(Ri)=rf+0×premium=rf.","Beta bằng 0 không khẳng định total volatility bằng 0; residual risk vẫn có thể cao."],"answer":"Required return bằng rf trong mô hình CAPM, không nhất thiết security risk-free."},{"id":"E07-01","los_ids":["CFA26-09-02-LOS07"],"problem":"rf=4%, market expected=10%, β=1,5.","solution_steps":["Market risk premium=10%−4%=6%.","CAPM required return=4%+1,5×6%=13%."],"answer":"Required E(Ri)=13%, cao hơn expected market return 10% vì beta 1,5 cho exposure thị trường lớn hơn 1."},{"id":"E07-02","los_ids":["CFA26-09-02-LOS07"],"problem":"Stock forecast=12%, rf=3%, market=9%, β=1. Tìm forecast alpha.","solution_steps":["CAPM required=3%+1×(9%−3%)=9%.","Expected alpha=forecast 12%−required 9%=3 điểm %.","Alpha dương theo forecast, chưa chứng minh cổ phiếu sẽ tăng giá."],"answer":"Forecast alpha=+3 điểm %."},{"id":"E08-01","los_ids":["CFA26-09-02-LOS08"],"problem":"Định giá công ty beta=1,3; rf=3%; MRP=5%. Cost of equity?","solution_steps":["ke=3%+1,3×5%=9,5%.","Đưa ke vào WACC với trọng số equity/other capital nếu phù hợp."],"answer":"Cost of equity 9,5% theo CAPM."},{"id":"E08-02","los_ids":["CFA26-09-02-LOS08"],"problem":"Dự án beta=2; corporate beta=0,8; rf=4%, MRP=6%. Hurdle rates?","solution_steps":["Required project=4%+2×6%=16%.","Required corporate common equity=4%+0,8×6%=8,8%.","Dùng 8,8% cho project beta=2 sẽ đánh giá dự án quá dễ dàng theo CAPM."],"answer":"Hurdle CAPM project 16% so với 8,8% của equity công ty."},{"id":"E09-01","los_ids":["CFA26-09-02-LOS09"],"problem":"Rp=12%, rf=2%, σp=20%, β=1,25; RM=10%, σM=15%. Tính bốn chỉ tiêu.","solution_steps":["Sharpe=(12−2)/20=0,50; Treynor=(12−2)/1,25=8% return per unit beta.","Jensen alpha=12−[2+1,25×(10−2)] =0 điểm %.","M² adjusted = 2%+0,50×15%=9,5%. M² relative =9,5%−10%=−0,5 điểm %."],"answer":"Sharpe=0,50; Treynor=8%; Jensen α=0%; M² adjusted 9,5%, relative −0,5%."},{"id":"E09-02","los_ids":["CFA26-09-02-LOS09"],"problem":"Portfolio X: Rp=10%, rf=2%, σ=10%; Portfolio Y: Rp=13%, rf=2%, σ=20%. So Sharpe.","solution_steps":["Sharpe X=(10−2)/10=0,8.","Sharpe Y=(13−2)/20=0,55.","X có excess return per total-risk tốt hơn dù raw return thấp hơn."],"answer":"X có Sharpe cao hơn, 0,80 so với 0,55."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-02-LOS01"],"stem":"Trộn 50% risk-free với risky portfolio σ=18%; σ combined là?","options":["18%","36%","9%"],"correct_option":2,"explanation":"Volatility kết hợp là |y|σp=0,5×18%=9% khi risk-free variance bằng 0. 18% bỏ qua phân bổ một nửa vào tài sản phi rủi ro; 36% giả định tăng gấp đôi vị thế rủi ro."},{"id":"Q01-02","los_ids":["CFA26-09-02-LOS01"],"stem":"Nếu y=1,5 nghĩa là?","options":["Borrowing 50% vốn để nắm 150% risky fund","Bán khống 150% risky fund","Lending 50% vốn"],"correct_option":0,"explanation":"Risk-free weight =1−1,5=−0,5, là khoản vay tài trợ risky position. Lending 50% là y=0,5; bán khống risky fund là y âm, không phải y dương 1,5."},{"id":"Q01-03","los_ids":["CFA26-09-02-LOS01"],"stem":"Treasury bond 30 năm có thể không risk-free trong chân trời 3 tháng vì?","options":["Không có coupon","Giá thị trường nhạy với thay đổi yield","Luôn vỡ nợ"],"correct_option":1,"explanation":"Giữ trong 3 tháng khiến long-duration bond có capital gain/loss dù issuer ít rủi ro default."},{"id":"Q02-01","los_ids":["CFA26-09-02-LOS02"],"stem":"Trục rủi ro của CML là?","options":["Credit spread","Beta","Total standard deviation"],"correct_option":2,"explanation":"CML đo total risk σ; beta là hoành độ của SML. Beta thuộc SML và credit spread không phải thước đo tổng volatility trên CML."},{"id":"Q02-02","los_ids":["CFA26-09-02-LOS02"],"stem":"CML là CAL của danh mục nào?","options":["Danh mục thị trường tại tangency","Mọi cổ phiếu riêng lẻ","Chỉ quỹ money market"],"correct_option":0,"explanation":"Trong CAPM cân bằng, tangency risky portfolio là market portfolio. Cổ phiếu riêng lẻ không nhất thiết efficient; cash tự nó không tạo risky tangency fund."},{"id":"Q02-03","los_ids":["CFA26-09-02-LOS02"],"stem":"rf=3%, E(RM)=9%, σM=15%, portfolio efficient σ=10%; E(Rp)=?","options":["9%","7%","5%"],"correct_option":1,"explanation":"E=3%+[(9−3)/15]×10%=7% trên đường CML. 9% là return của toàn market tại σ=15%, còn danh mục này chỉ chịu σ=10% nên nhận premium thấp hơn."},{"id":"Q03-01","los_ids":["CFA26-09-02-LOS03"],"stem":"Loại rủi ro CAPM trả expected risk premium?","options":["Unsystematic","Specific","Systematic"],"correct_option":2,"explanation":"Risk premium theo CAPM phụ thuộc beta, là exposure to marketwide systematic risk."},{"id":"Q03-02","los_ids":["CFA26-09-02-LOS03"],"stem":"Cổ phiếu σ cao do công ty sắp được phê duyệt thuốc có thể có beta?","options":["Bất kỳ, kể cả thấp","Bắt buộc cao","Bắt buộc bằng 1"],"correct_option":0,"explanation":"Total volatility có thể bị chi phối bởi idiosyncratic shocks không tương quan với market."},{"id":"Q03-03","los_ids":["CFA26-09-02-LOS03"],"stem":"Rủi ro lỗi sản xuất riêng một công ty được gọi?","options":["Inflation risk","Unsystematic risk","Interest rate policy risk"],"correct_option":1,"explanation":"Company-specific operational shock là nguồn unsystematic risk có thể giảm khi diversification."},{"id":"Q04-01","los_ids":["CFA26-09-02-LOS04"],"stem":"Residual trong market model thường biểu thị?","options":["Lãi suất trái phiếu phi rủi ro","Expected return của CAPM","Phần lợi suất chưa giải thích bởi nhân tố thị trường"],"correct_option":2,"explanation":"Residual ε chứa yếu tố idiosyncratic và nhiễu ước lượng không do beta×market return giải thích."},{"id":"Q04-02","los_ids":["CFA26-09-02-LOS04"],"stem":"Thay đổi CPI được sử dụng như một factor trong mô hình nào?","options":["Macroeconomic factor model","Công thức duration modified duy nhất","Chỉ statistical không diễn giải"],"correct_option":0,"explanation":"Inflation là biến vĩ mô có ý nghĩa kinh tế, có thể là systematic factor trong macro model."},{"id":"Q04-03","los_ids":["CFA26-09-02-LOS04"],"stem":"Market model và CAPM có đồng nhất không?","options":["Có nếu thị trường tăng","Không; một mô hình thực nghiệm returns, một mô hình định giá kỳ vọng ở trạng thái cân bằng","Có vì cả hai có beta"],"correct_option":1,"explanation":"Market model hồi quy Ri lên Rm; CAPM giả định E(Ri)=rf+β(E(Rm)−rf). Trùng beta không có nghĩa hai mô hình có cùng giả định, mục đích và kết quả dự báo."},{"id":"Q05-01","los_ids":["CFA26-09-02-LOS05"],"stem":"Beta được tính từ covariance và market variance là?","options":["Cov/σi","Var(RM)/Cov","Cov(Ri,RM)/Var(RM)"],"correct_option":2,"explanation":"β=Cov(asset,market)/Var(market); không chia cho standard deviation riêng. Đảo tỷ số sẽ ra beta nghịch đảo, còn Cov/σi sai đơn vị và không phải slope hồi quy."},{"id":"Q05-02","los_ids":["CFA26-09-02-LOS05"],"stem":"Cov=0,024, market variance=0,016; β?","options":["1,5","0,67","0,4"],"correct_option":0,"explanation":"Beta =0,024/0,016=1,5. 0,67 là nghịch đảo của beta đúng; 0,4 không xuất phát từ covariance/variance đã cho."},{"id":"Q05-03","los_ids":["CFA26-09-02-LOS05"],"stem":"Thêm 50% risk-free vào stock beta=1,2 sẽ tạo beta danh mục?","options":["2,4","0,6","1,2"],"correct_option":1,"explanation":"βp=0,5×1,2+0,5×0=0,6. Phần risk-free có beta=0 nên đóng góp 0; không cộng beta mà không xét tỷ trọng."},{"id":"Q06-01","los_ids":["CFA26-09-02-LOS06"],"stem":"Trục ngang SML là?","options":["σ total","Sharpe ratio","Beta"],"correct_option":2,"explanation":"SML dùng beta là systematic risk; CML dùng total σ. Total σ được dùng trên CML; Sharpe là slope đánh giá hiệu quả chứ không phải trục x SML."},{"id":"Q06-02","los_ids":["CFA26-09-02-LOS06"],"stem":"Security beta=0 có CAPM required return?","options":["rf","0%","Market expected return"],"correct_option":0,"explanation":"SML cắt trục lợi suất tại rf khi beta=0. Beta=0 vẫn có thể có company-specific risk; không được mặc định required return là 0% hoặc return thị trường."},{"id":"Q06-03","los_ids":["CFA26-09-02-LOS06"],"stem":"Trong CAPM, giả định nào hỗ trợ việc dùng market portfolio là tangency fund?","options":["Mỗi nhà đầu tư có chi phí giao dịch riêng rất khác nhau","Kỳ vọng đồng nhất và cùng cơ hội vay/cho vay phi rủi ro","Không được đa dạng hóa tài sản"],"correct_option":1,"explanation":"Homogeneous expectations và frictionless access cho cùng risky efficient portfolio trong mô hình cân bằng."},{"id":"Q07-01","los_ids":["CFA26-09-02-LOS07"],"stem":"rf=4%, E(RM)=10%, β=1,5; CAPM return?","options":["10%","15%","13%"],"correct_option":2,"explanation":"rf+β×MRP=4%+1,5×(10%−4%)=13%. 10% là market return, còn 15% không bằng rf cộng beta nhân premium 6%; phải cộng rf sau khi nhân."},{"id":"Q07-02","los_ids":["CFA26-09-02-LOS07"],"stem":"β âm và market premium dương cho CAPM required return:","options":["Có thể thấp hơn rf","Bằng rf","Luôn cao hơn market"],"correct_option":0,"explanation":"SML với positive slope: negative beta nằm bên trái 0 và required return dưới rf."},{"id":"Q07-03","los_ids":["CFA26-09-02-LOS07"],"stem":"Forecast return 12%, required CAPM 9%; expected alpha?","options":["0%","+3%","−3%"],"correct_option":1,"explanation":"Forecast alpha là chênh lệch forecast return trừ benchmark required return, bằng +3 điểm %."},{"id":"Q08-01","los_ids":["CFA26-09-02-LOS08"],"stem":"Ứng dụng CAPM để chiết khấu FCFE thường dùng?","options":["Before-tax cost of debt","Lãi suất tiền gửi qua đêm duy nhất","Cost of equity"],"correct_option":2,"explanation":"FCFE thuộc cổ đông, thường dùng ke dựa trên risk của equity; WACC thường dùng cho FCFF."},{"id":"Q08-02","los_ids":["CFA26-09-02-LOS08"],"stem":"Stock dự báo E=13%, SML yêu cầu=10%; relative expected alpha?","options":["+3%","+10%","−3%"],"correct_option":0,"explanation":"Dự báo vượt required return 3 điểm %, gợi ý above SML theo dự báo. Dấu dương có nghĩa forecast cao hơn required; 10% là required return chứ không phải alpha."},{"id":"Q08-03","los_ids":["CFA26-09-02-LOS08"],"stem":"Dự án beta cao hơn company beta, dùng companywide required equity return có thể?","options":["Không làm khác quyết định đầu tư","Đặt hurdle rate quá thấp so với systematic risk dự án","Luôn yêu cầu cao hơn mức phù hợp"],"correct_option":1,"explanation":"Project cần risk-adjusted discount rate theo beta riêng nếu rủi ro có thể đo phù hợp."},{"id":"Q09-01","los_ids":["CFA26-09-02-LOS09"],"stem":"Sharpe ratio dùng mẫu số?","options":["Beta","Variance","Standard deviation"],"correct_option":2,"explanation":"Sharpe đo excess return trên total volatility σ, không dùng beta hay σ². Beta thuộc Treynor; variance là bình phương σ, không dùng làm mẫu số Sharpe."},{"id":"Q09-02","los_ids":["CFA26-09-02-LOS09"],"stem":"Rp=12%, rf=2%, β=1,25; Treynor =?","options":["8%","10%","12,5%"],"correct_option":0,"explanation":"Treynor = (12%−2%)/1,25=8% return per beta unit. 10% là excess return chưa điều chỉnh beta; 12,5% không bằng phép chia 10% cho 1,25."},{"id":"Q09-03","los_ids":["CFA26-09-02-LOS09"],"stem":"Sharpe=0,5, rf=2%, market σ=15%; M² adjusted return?","options":["7,5%","9,5%","10,0%"],"correct_option":1,"explanation":"M² adjusted = rf+Sharpe×σMarket =2%+0,5×15%=9,5%. 7,5% mới chỉ là adjusted excess return, chưa cộng rf 2%; 10% là market return trong một ví dụ khác."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-02-LOS01"],"front":"Điều kiện của risk-free asset — giải thích bản chất?","back":"Risk-free asset trong mô hình có lợi suất chắc chắn cùng thời hạn đầu tư và đơn vị tiền tệ với khoản phân bổ; vì vậy σrf=0 và covariance với risky asset bằng 0. Trái phiếu chính phủ dài hạn vẫn có market-price risk nếu bán trước kỳ hạn."},{"id":"C01-02","los_ids":["CFA26-09-02-LOS01"],"front":"Biến đổi phân phối lợi suất — giải thích bản chất?","back":"Nếu dành tỷ trọng y vào risky portfolio và 1−y vào risk-free, E(Rc)=rf+y(E(Rp)−rf), σc=|y|σp. Tỷ trọng y nhỏ làm giảm total volatility và expected excess return tỷ lệ thuận trong giả định mô hình."},{"id":"C01-03","los_ids":["CFA26-09-02-LOS01"],"front":"Lending, borrowing và leverage — giải thích bản chất?","back":"Với 0≤y≤1 nhà đầu tư trộn cash và risky fund; y>1 nghĩa là vay bằng negative risk-free weight để giữ vị thế risky lớn hơn vốn tự có. Vay ngoài thực tế có lãi suất cao hơn rf và margin constraints nên đường cơ hội có thể gãy khúc."},{"id":"C02-01","los_ids":["CFA26-09-02-LOS02"],"front":"CAL cho từng risky portfolio — giải thích bản chất?","back":"CAL vẽ các phối hợp expected return và standard deviation từ một risky portfolio P với risk-free asset; trục x là total risk σ, trục y E(R). Mỗi P có một CAL riêng với slope Sharpe(P)."},{"id":"C02-02","los_ids":["CFA26-09-02-LOS02"],"front":"CML là CAL đặc biệt — giải thích bản chất?","back":"Trong thế giới CAPM cân bằng và giả định đồng nhất, market portfolio M là tangency risky portfolio; CAL qua rf và M được gọi Capital Market Line (CML). Tài sản hoặc danh mục không efficient nằm ngoài CML, nên không tính E(Ri) theo CML cho cổ phiếu riêng lẻ."},{"id":"C02-03","los_ids":["CFA26-09-02-LOS02"],"front":"Lending và borrowing dọc CML — giải thích bản chất?","back":"Điểm giữa rf và M là kết hợp cash với market portfolio. Điểm phía phải M là leverage market portfolio; nếu lãi vay khác lãi cho vay, cơ hội đầu tư không còn đường thẳng duy nhất và CML lý thuyết không khớp."},{"id":"C03-01","los_ids":["CFA26-09-02-LOS03"],"front":"Systematic risk — giải thích bản chất?","back":"Market risk xuất phát từ những nhân tố tác động diện rộng như tăng trưởng, lạm phát và monetary policy. Một danh mục đa dạng hóa vẫn chịu các biến động chung; CAPM định giá phần này qua beta."},{"id":"C03-02","los_ids":["CFA26-09-02-LOS03"],"front":"Nonsystematic risk — giải thích bản chất?","back":"Company-specific hoặc sector-specific shocks như thay đổi CEO, product recall, lawsuit có thể giảm qua việc kết hợp nhiều khoản đầu tư ít tương quan. Khi số lượng tài sản đa dạng tăng lên, tổng rủi ro giảm nhưng tiến về mức systematic risk thay vì 0."},{"id":"C03-03","los_ids":["CFA26-09-02-LOS03"],"front":"Tại sao không có premium cho unsystematic risk — giải thích bản chất?","back":"Nhà đầu tư có thể loại bỏ phần lớn idiosyncratic risk với chi phí thấp bằng đa dạng hóa; thị trường cân bằng không phải trả thêm expected return chỉ vì nhà đầu tư tự nguyện giữ danh mục tập trung."},{"id":"C04-01","los_ids":["CFA26-09-02-LOS04"],"front":"Return-generating models là gì — giải thích bản chất?","back":"Các mô hình quy lợi suất của chứng khoán về các nhân tố thống kê, kinh tế vĩ mô hoặc đặc trưng cơ bản. Mô hình giúp ước lượng exposure, scenario analysis, attribution và risk management, nhưng kết quả phụ thuộc nhân tố chọn, phương pháp ước lượng và dữ liệu."},{"id":"C04-02","los_ids":["CFA26-09-02-LOS04"],"front":"Market model — giải thích bản chất?","back":"Một mô hình thời gian: R_i=α_i+β_iR_M+ε_i. β_i là slope tuyến tính giữa security return và market return, α intercept, ε specific return không giải thích bởi market. Market model là mô hình thực nghiệm, không tự đồng nhất với expected CAPM pricing equation."},{"id":"C04-03","los_ids":["CFA26-09-02-LOS04"],"front":"Macroeconomic và fundamental factor models — giải thích bản chất?","back":"Macro factors có thể gồm inflation surprise, GDP growth, interest-rate shock; fundamental factors gồm size, value, profitability. Exposure và factor returns có thể mang các đơn vị khác nhau; cần xác định ý nghĩa của hệ số để giải thích."},{"id":"C05-01","los_ids":["CFA26-09-02-LOS05"],"front":"Beta đo market sensitivity — giải thích bản chất?","back":"β_i=Cov(R_i,R_M)/Var(R_M), là slope regression market model. Beta=1: biến động trung bình cùng chiều với market theo slope khoảng 1; beta>1 nhạy hơn; beta<0 thường biến động trái chiều với market."},{"id":"C05-02","los_ids":["CFA26-09-02-LOS05"],"front":"Beta không bằng volatility — giải thích bản chất?","back":"Cổ phiếu có β=1,5 không nhất thiết có σ cao gấp 1,5 thị trường vì còn residual risk. Beta có thể tính bằng ρ_iM(σ_i/σ_M) khi standard deviations dương."},{"id":"C05-03","los_ids":["CFA26-09-02-LOS05"],"front":"Beta danh mục — giải thích bản chất?","back":"βp=Σw_iβ_i nếu trọng số dollar và beta cùng market benchmark. Với risk-free β=0, mix 50% stock β=1,2 và 50% risk-free cho βp=0,6."},{"id":"C06-01","los_ids":["CFA26-09-02-LOS06"],"front":"CAPM và market risk premium — giải thích bản chất?","back":"CAPM liên hệ expected required return với exposure to market portfolio: E(R_i)=r_f+β_i[E(R_M)−r_f]. Market premium là E(RM)−rf, không phải observed market return trừ market return kỳ trước."},{"id":"C06-02","los_ids":["CFA26-09-02-LOS06"],"front":"Ý nghĩa SML — giải thích bản chất?","back":"SML đặt β trên trục x và required expected return trên trục y. SML intercept r_f tại β=0, slope market premium. Security nằm trên SML được định giá phù hợp CAPM, security nằm trên đường cần so với investor expected return để đánh giá alpha."},{"id":"C06-03","los_ids":["CFA26-09-02-LOS06"],"front":"Các giả định điển hình — giải thích bản chất?","back":"Nhà đầu tư tối đa hóa mean-variance utility một kỳ; kỳ vọng đồng nhất; tài sản phân chia, mua bán không ma sát; không có taxes/transaction costs; có thể vay và cho vay ở rf; thị trường cạnh tranh và cùng tập cơ hội."},{"id":"C07-01","los_ids":["CFA26-09-02-LOS07"],"front":"Chọn đúng market premium — giải thích bản chất?","back":"Lấy expected market return trừ đúng risk-free rate cùng kỳ, cùng currency. Đề có realized market return kỳ trước thì chưa đủ để làm expected premium nếu không chỉ định."},{"id":"C07-02","los_ids":["CFA26-09-02-LOS07"],"front":"Tính required return — giải thích bản chất?","back":"Dùng β×market risk premium rồi cộng rf. Nếu beta âm và premium dương, required return thấp hơn rf; β>1 có required return cao hơn market theo CAPM."},{"id":"C07-03","los_ids":["CFA26-09-02-LOS07"],"front":"Kiểm tra valuation so với forecast — giải thích bản chất?","back":"Analyst forecast E(Ri) lớn hơn CAPM required return có positive expected alpha trong cùng mô hình và giả định; không tự động có arbitrage profit. Forecast không chắc chắn và beta có thể thay đổi."},{"id":"C08-01","los_ids":["CFA26-09-02-LOS08"],"front":"Cost of equity và discount rate — giải thích bản chất?","back":"CAPM được dùng để ước lượng shareholders’ required return k_e trong định giá cổ phiếu/DCF và WACC. Beta nên phản ánh business/financial risk của khoản đầu tư, không dùng beta của công ty khác không tương đồng."},{"id":"C08-02","los_ids":["CFA26-09-02-LOS08"],"front":"Capital budgeting — giải thích bản chất?","back":"Dự án có beta cao hơn hoạt động lõi cần required return/hurdle rate phù hợp, không nhất thiết dùng companywide WACC. Áp dụng dự án theo SML để xác định suất sinh lợi yêu cầu cho systematic risk."},{"id":"C08-03","los_ids":["CFA26-09-02-LOS08"],"front":"Security selection và alpha — giải thích bản chất?","back":"So expected return analyst forecast với SML benchmark: above-SML (alpha dương) có thể hàm ý underpriced theo dự báo; below-SML (alpha âm) có thể hàm ý overpriced. Không đồng nghĩa chắc chắn có cơ hội chênh lệch giá phi rủi ro."},{"id":"C09-01","los_ids":["CFA26-09-02-LOS09"],"front":"Sharpe ratio — giải thích bản chất?","back":"Sharpe=(Rp−rf)/σp đo excess return trên total standard deviation, hữu ích khi so các danh mục không nhất thiết đã đa dạng hóa. Nếu σ=0 thì không định nghĩa; Sharpe âm cần thận trọng khi so với volatility."},{"id":"C09-02","los_ids":["CFA26-09-02-LOS09"],"front":"Treynor ratio — giải thích bản chất?","back":"Treynor=(Rp−rf)/βp đo excess return trên systematic risk; phù hợp hơn với fully diversified portfolios. Khi beta gần 0, bằng 0 hoặc âm, tỷ lệ khó diễn giải và xếp hạng có thể sai."},{"id":"C09-03","los_ids":["CFA26-09-02-LOS09"],"front":"Jensen alpha — giải thích bản chất?","back":"αp=Rp−[rf+βp(RM−rf)] đo chênh lệch return thực hiện/dự báo với CAPM benchmark trong cùng kỳ. Có thể khác forecast alpha dựa expected future return."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_source_PDFs"}]);
window.CFA_AUDIT_TOTALS=(function(previous){previous=previous||{};return {...previous,drafted:Math.max(Number(previous.drafted)||0,320),independently_reaudited:Math.max(Number(previous.independently_reaudited)||0,177),scope:"Targeted LOS three-source review; not exhaustive textbook verification"};})(window.CFA_AUDIT_TOTALS);
